<?php
$record = $record ?? [];
$mode = $mode ?? 'create';
$items = $record['items'] ?? [['quantity' => 1, 'hs_code' => '99001000', 'description' => '', 'unit_price' => '', 'vat_rate' => 15.5]];
$esc = static fn ($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$formAction = '/index.php?controller=accounting&action=' . ($mode === 'edit' ? 'invoiceEdit&id=' . (int) ($recordId ?? 0) : 'invoiceCreate');
?>
<div class="d-flex justify-content-between align-items-start mb-4">
    <div><div class="eyebrow">Accounting · Invoices</div><h1 class="page-title"><?= $esc($title ?? 'Fiscal Tax Invoice') ?></h1><p class="page-subtitle">Capture customer tax details and invoice lines in the Kubasa fiscal-tax format.</p></div>
    <?php if ($mode === 'edit'): ?><a class="btn btn-outline-secondary" href="/index.php?controller=accounting&amp;action=invoicePrint&amp;id=<?= (int) ($recordId ?? 0) ?>">Preview invoice</a><?php endif; ?>
</div>
<?php if (!empty($error)): ?><div class="alert alert-danger" role="alert"><?= $esc($error) ?></div><?php endif; ?>
<form method="post" action="<?= $esc($formAction) ?>" id="invoice-form" class="vstack gap-4">
    <?= $this->csrfField() ?>
    <section class="card"><div class="card-body"><h2 class="h5 mb-3">Invoice details</h2><div class="row g-3">
        <?php if ($mode === 'create'): ?><div class="col-md-6"><label class="form-label" for="sale_id">Sale to invoice</label><select id="sale_id" name="sale_id" class="form-select" required><option value="">Choose an unbilled sale</option><?php foreach (($sales ?? []) as $sale): ?><option value="<?= (int) $sale['id'] ?>" data-name="<?= $esc($sale['client_name'] ?? '') ?>" data-email="<?= $esc($sale['client_email'] ?? '') ?>" data-phone="<?= $esc($sale['client_phone'] ?? '') ?>" data-address="<?= $esc($sale['client_address'] ?? '') ?>" <?= (string) ($record['sale_id'] ?? '') === (string) $sale['id'] ? 'selected' : '' ?>>Sale #<?= (int) $sale['id'] ?> · <?= $esc($sale['client_name'] ?? 'Walk-in') ?> · $<?= number_format((float) $sale['total_amount'], 2) ?></option><?php endforeach; ?></select><?php if (empty($sales)): ?><div class="form-text">There are no unbilled sales yet. Record a sale before creating an invoice.</div><?php endif; ?></div><?php else: ?><div class="col-md-6"><label class="form-label">Sale</label><input class="form-control" value="Sale #<?= (int) ($record['sale_id'] ?? 0) ?> · <?= $esc($record['client_name'] ?? '') ?>" disabled></div><input type="hidden" name="sale_id" value="<?= (int) ($record['sale_id'] ?? 0) ?>"><?php endif; ?>
        <div class="col-md-3"><label class="form-label" for="issue_date">Invoice date</label><input class="form-control" type="date" id="issue_date" name="issue_date" value="<?= $esc($record['issue_date'] ?? date('Y-m-d')) ?>" required></div>
        <div class="col-md-3"><label class="form-label" for="due_date">Due date</label><input class="form-control" type="date" id="due_date" name="due_date" value="<?= $esc($record['due_date'] ?? '') ?>" required></div>
        <div class="col-md-3"><label class="form-label" for="currency">Currency</label><select class="form-select" id="currency" name="currency"><option value="USD" <?= ($record['currency'] ?? 'USD') === 'USD' ? 'selected' : '' ?>>USD</option><option value="ZWG" <?= ($record['currency'] ?? '') === 'ZWG' ? 'selected' : '' ?>>ZWG</option></select></div>
        <div class="col-md-3"><label class="form-label" for="status">Status</label><select class="form-select" id="status" name="status"><?php foreach (['unpaid','paid','partial','overdue'] as $status): ?><option value="<?= $esc($status) ?>" <?= ($record['status'] ?? 'unpaid') === $status ? 'selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select></div>
        <div class="col-md-3"><label class="form-label" for="reference_number">Reference number</label><input class="form-control" id="reference_number" name="reference_number" value="<?= $esc($record['reference_number'] ?? '') ?>" placeholder="Defaults to invoice number"></div>
        <div class="col-md-3"><label class="form-label" for="sales_person">Sales person</label><input class="form-control" id="sales_person" name="sales_person" value="<?= $esc($record['sales_person'] ?? ($_SESSION['user']['name'] ?? '')) ?>"></div>
    </div></div></section>
    <section class="card"><div class="card-body"><h2 class="h5 mb-3">Customer details</h2><div class="row g-3">
        <?php foreach ([['customer_registered_name','Registered name'],['customer_trade_name','Trade name'],['customer_address','Address'],['customer_email','Email'],['customer_phone','Tel / mobile'],['customer_tin','Customer TIN no.'],['customer_vat','Customer VAT no.']] as [$name,$label]): ?><div class="col-md-6"><label class="form-label" for="<?= $name ?>"><?= $label ?></label><input class="form-control" id="<?= $name ?>" name="<?= $name ?>" value="<?= $esc($record[$name] ?? '') ?>" <?= $name === 'customer_address' ? 'placeholder="Customer address"' : '' ?>></div><?php endforeach; ?>
    </div></div></section>
    <section class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 mb-1">Invoice lines</h2><p class="small text-secondary mb-0">Enter quantities and prices excluding VAT. Line totals are calculated automatically.</p></div><button class="btn btn-sm btn-outline-primary" type="button" id="add-invoice-line"><i class="fa-solid fa-plus me-1"></i>Add line</button></div>
        <div class="table-responsive"><table class="table align-middle" id="invoice-lines-table"><thead><tr><th>Qty</th><th>HS code</th><th>Description</th><th>Unit price</th><th>VAT %</th><th></th></tr></thead><tbody>
        <?php foreach ($items as $i => $item): ?><tr class="invoice-line"><td><input class="form-control form-control-sm" type="number" min="0.001" step="0.001" name="items[<?= (int) $i ?>][quantity]" value="<?= $esc($item['quantity'] ?? 1) ?>" required></td><td><input class="form-control form-control-sm" name="items[<?= (int) $i ?>][hs_code]" value="<?= $esc($item['hs_code'] ?? '99001000') ?>"></td><td><input class="form-control form-control-sm" name="items[<?= (int) $i ?>][description]" value="<?= $esc($item['description'] ?? '') ?>" required></td><td><input class="form-control form-control-sm" type="number" min="0" step="0.01" name="items[<?= (int) $i ?>][unit_price]" value="<?= $esc($item['unit_price'] ?? '') ?>" required></td><td><input class="form-control form-control-sm" type="number" min="0" max="100" step="0.001" name="items[<?= (int) $i ?>][vat_rate]" value="<?= $esc($item['vat_rate'] ?? 15.5) ?>" required></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-line" aria-label="Remove line"><i class="fa-solid fa-trash"></i></button></td></tr><?php endforeach; ?>
        </tbody></table></div>
        <div class="d-flex justify-content-end"><div class="invoice-totals"><div>Subtotal excl. <strong id="preview-subtotal">—</strong></div><div>VAT total <strong id="preview-vat">—</strong></div><div class="fs-5">Invoice total <strong id="preview-total">—</strong></div></div></div>
    </div></section>
    <div class="d-flex gap-2"><button class="btn btn-primary" type="submit">Save invoice</button><a class="btn btn-outline-secondary" href="/index.php?controller=accounting&amp;action=invoices">Cancel</a></div>
</form>
<script>
(() => {
 const tbody=document.querySelector('#invoice-lines-table tbody'); let nextIndex=<?= count($items) ?>;
 const addLine=(line={})=>{const i=nextIndex++;const tr=document.createElement('tr');tr.className='invoice-line';tr.innerHTML=`<td><input class="form-control form-control-sm" type="number" min="0.001" step="0.001" name="items[${i}][quantity]" value="${line.quantity??1}" required></td><td><input class="form-control form-control-sm" name="items[${i}][hs_code]" value="${line.hs_code??'99001000'}"></td><td><input class="form-control form-control-sm" name="items[${i}][description]" value="" required></td><td><input class="form-control form-control-sm" type="number" min="0" step="0.01" name="items[${i}][unit_price]" value="" required></td><td><input class="form-control form-control-sm" type="number" min="0" max="100" step="0.001" name="items[${i}][vat_rate]" value="15.5" required></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-line" aria-label="Remove line"><i class="fa-solid fa-trash"></i></button></td>`;tbody.append(tr);};
 document.getElementById('add-invoice-line').addEventListener('click',()=>addLine());
 tbody.addEventListener('click',e=>{if(e.target.closest('.remove-line')){if(tbody.querySelectorAll('.invoice-line').length>1)e.target.closest('.invoice-line').remove();recalculate();}});
 const currency=()=>document.getElementById('currency').value;
 const fmt=v=>new Intl.NumberFormat(undefined,{style:'currency',currency:currency()}).format(v||0);
 const recalculate=()=>{let subtotal=0,vat=0;tbody.querySelectorAll('.invoice-line').forEach(tr=>{const q=Number(tr.querySelector('[name$="[quantity]"]').value)||0,p=Number(tr.querySelector('[name$="[unit_price]"]').value)||0,r=Number(tr.querySelector('[name$="[vat_rate]"]').value)||0;subtotal+=q*p;vat+=q*p*r/100;});document.getElementById('preview-subtotal').textContent=fmt(subtotal);document.getElementById('preview-vat').textContent=fmt(vat);document.getElementById('preview-total').textContent=fmt(subtotal+vat);};
 tbody.addEventListener('input',recalculate);document.getElementById('currency').addEventListener('change',()=>{const rate=document.getElementById('currency').value==='ZWG'?'15':'15.5';tbody.querySelectorAll('[name$="[vat_rate]"]').forEach(input=>input.value=rate);recalculate();});recalculate();
 const saleSelect=document.getElementById('sale_id');saleSelect?.addEventListener('change',()=>{const o=saleSelect.selectedOptions[0];if(!o?.value)return;for(const [field,key] of [['customer_registered_name','name'],['customer_trade_name','name'],['customer_email','email'],['customer_phone','phone'],['customer_address','address']]){const input=document.getElementById(field);if(input&&!input.value)input.value=o.dataset[key]||'';}});if(saleSelect?.value)saleSelect.dispatchEvent(new Event('change'));
})();
</script>
<style>.invoice-totals{min-width:260px;display:grid;gap:8px}.invoice-totals>div{display:flex;justify-content:space-between;gap:24px}.invoice-line input{min-width:90px}@media(max-width:760px){#invoice-lines-table{min-width:760px}}</style>
